detaileddescription.para:
Usage Example: TaskSchedulerscheduler(query_engine);

//Scheduleadatacompressiontask
ScheduledTaskcompression_task;
compression_task.id="compress_old_data";
compression_task.name="CompressOldTimeSeriesData";
compression_task.type=ScheduledTask::TaskType::AQL_QUERY;
compression_task.aql_query="FORdINtimeseriesFILTERd.timestamp<DATE_SUB(NOW(),1,'day')"
"UPDATEdWITH{compressed:true}INtimeseries";
compression_task.interval=std::chrono::hours(6);

scheduler.registerTask(compression_task);
scheduler.start();

//...schedulerrunsinbackground...

scheduler.stop();
